        scores[key] = value
    return scores

def average(scores: dict) -> float:
    if not scores:
        return 0.0
    total = sum(float(v) for v in scores.values())
    return total / len(scores)

def rank_top(scores: dict, k: int) -> list:
    if k <= 0:
        return []
    items = sorted(scores.items(), key=lambda kv: float(kv[1]), reverse=True)
    return items[:k]

