    assert average({"a": 1, "b": 2, "c": 3, "d": 4}) == pytest.approx(2.5)


def test_average_ignores_keys_and_uses_values_only():
    """Only values participate in the mean, keys are irrelevant."""
    assert average({"long-key-name": 5, "z": 15}) == pytest.approx(10.0)


def test_average_returns_float():
    """The documented return type is float, even for integral inputs."""
    result = average({"a": 2, "b": 4})
    assert isinstance(result, float)
    assert result == pytest.approx(3.0)


def test_average_with_negative_values():
    """Negative values must be included in the sum."""
    assert average({"a": -5, "b": 5, "c": 0}) == pytest.approx(0.0)


def test_average_zero_valued_entries_is_zero():
    """All-zero values give a zero mean regardless of how many entries exist."""
    assert average({"a": 0, "b": 0, "c": 0}) == pytest.approx(0.0)


