def test_rank_top_orders_by_score_descending():
    """The returned pairs must be sorted from highest score to lowest."""
    scores = {"a": 3, "b": 9, "c": 1}
    assert rank_top(scores, 3) == [("b", 9), ("a", 3), ("c", 1)]


def test_rank_top_truncates_to_k():
    """Only the best k entries are returned when more are available."""
    scores = {"a": 3, "b": 9, "c": 1, "d": 7}
    assert rank_top(scores, 2) == [("b", 9), ("d", 7)]


def test_rank_top_k_zero_returns_empty_list():
    """Requesting the top 0 entries yields nothing."""
    scores = {"a": 3, "b": 9}
    assert rank_top(scores, 0) == []


def test_rank_top_k_larger_than_population_returns_all_sorted():
    """A k above the population size returns every entry, still sorted."""
    scores = {"a": 1, "b": 2}
    assert rank_top(scores, 10) == [("b", 2), ("a", 1)]


def test_rank_top_empty_scores_returns_empty_list():
    """Ranking an empty mapping produces an empty list."""
    assert rank_top({}, 3) == []


def test_rank_top_negative_k_returns_empty_list():
    """A negative k denotes 'no top entries'.

    'Top k' is only defined for k >= 0; there is no such thing as a
    negative number of leading entries, so the result must be empty.
    Expected value derived from the 'top-k' contract, not from the
    slicing behaviour of the implementation.
    """
    scores = {"a": 3, "b": 9, "c": 1}
    assert rank_top(scores, -1) == []


@pytest.mark.parametrize("k", [-5, -2, -1])
def test_rank_top_any_negative_k_returns_empty_list(k):
    """Every negative k must collapse to the empty selection."""
    scores = {"a": 3, "b": 9, "c": 1, "d": 7}
    assert rank_top(scores, k) == []


def test_rank_top_does_not_mutate_input():
    """Ranking is a read-only operation on the scores mapping."""
    scores = {"a": 3, "b": 9, "c": 1}
    snapshot = dict(scores)
    rank_top(scores, 2)
    assert scores == snapshot


def test_rank_top_result_entries_are_name_value_pairs():
    """Each returned element pairs the key with its own value."""
    scores = {"alice": 4, "bob": 8}
    result = rank_top(scores, 2)
    assert result == [("bob", 8), ("alice", 4)]
    for name, value in result:
        assert scores[name] == value

